parameters.jsCode:
const now = new Date();
now.setHours(now.getHours()); // Ajuste manual a UTC+2

const fecha = now.toLocaleDateString('es-ES', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
}).replace(/^\w/, c => c.toUpperCase());

const hora = now.toLocaleTimeString('es-ES', {
  hour: '2-digit',
  minute: '2-digit'
});

return [{ json: { fecha, hora } }];

// Accede al nodo "Obtiene todos los Mensajes"
const mensajes = $items("Obtiene todos los Mensajes")[0].json.message;

// Verifica que es un array y lo invierte
const mensajesInvertidos = Array.isArray(mensajes) ? [...mensajes].reverse() : [];

return [
  {
    json: {
      mensajes_invertidos: mensajesInvertidos
    }
  }
];

